from functools import lru_cache

def count_digit(upper={{upper}}):
    s = str(upper)
    @lru_cache(None)
    def dp(pos, tight, started, sum_d):
        if pos == len(s): return sum_d if started else 0
        lim = int(s[pos]) if tight else 9
        total = 0
        for d in range(0, lim+1):
            total += dp(pos+1, tight and d == lim, started or d > 0, sum_d + d)
        return total
    return dp(0, True, False, 0)
